'use strict';
const $=s=>document.querySelector(s), key='ombaliz-schemas-v1';
let state={ratings:{},notes:{},name:'',patientEmail:'',patientPhone:'',priority:'',situation:'',need:'',action:''},group=0,activeSchema=0;
try{const s=JSON.parse(localStorage.getItem(key));if(s&&s.ratings&&s.notes){state={...state,...s};$('#save').checked=true;}}catch{}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){if($('#save').checked){try{localStorage.setItem(key,JSON.stringify(state));}catch{$('#status').textContent='La conservation locale est indisponible. Téléchargez votre bilan avant de fermer.';}}}
function figure(i){
 const person=(x,y,color='#a13b52',pose='normal')=>`<g transform="translate(${x} ${y})"><circle cy="-26" r="13" fill="#efccb1" stroke="#205c6a" stroke-width="2"/><path d="M-12 -30Q-10 -48 10 -34" fill="#205c6a"/><path d="M-13 -10Q0 -17 13 -10L18 24H-18Z" fill="${color}"/><path d="M-7 24L-13 47M7 24L16 47M-12 -5L-29 ${pose==='reach'?-18:15}M12 -5L31 ${pose==='reach'?-20:15}" stroke="#205c6a" stroke-width="5" stroke-linecap="round" fill="none"/><path d="M-5 -27h1m8 0h1M-5 -19q5 ${pose==='sad'?-4:3} 10 0" stroke="#205c6a" stroke-width="1.7" fill="none"/></g>`;
 const label=(x,y,t)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#205c6a" font-size="13" font-family="system-ui,sans-serif">${t}</text>`;
 const box=(x,y,w,h,t)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" fill="#fffdf8" stroke="#9cb3a7" stroke-width="2"/>${label(x+w/2,y+h/2+5,t)}`;
 const heart=(x,y)=>`<path transform="translate(${x} ${y})" d="M0 5C-18 -12 -22 9 0 23C22 9 18 -12 0 5Z" fill="#a13b52"/>`;
 const scene=[
 person(115,112,'#a13b52','reach')+person(275,112,'#7c9b91')+'<path d="M172 105h48" stroke="#a13b52" stroke-width="3" stroke-dasharray="5 7"/>'+box(247,30,68,23,'Départ')+label(160,186,'La distance réveille la peur de perdre le lien.'),
 person(110,112,'#a13b52','sad')+person(264,112,'#7c9b91')+'<path d="M168 62L206 78V117Q188 147 168 117Z" fill="#dae4dc" stroke="#205c6a" stroke-width="3"/>'+label(188,110,'?')+label(185,186,'Je reste sur mes gardes pour me protéger.'),
 person(175,112,'#a13b52','sad')+box(43,23,96,33,'Écoute ?')+box(238,45,95,33,'Soutien ?')+'<path d="M139 52l20 20M237 76l-25 15" stroke="#9cb3a7" stroke-width="2" stroke-dasharray="4 5"/>'+label(185,186,'Je ne me sens pas rejoint dans mes besoins.'),
 person(110,112,'#a13b52','sad')+'<rect x="222" y="28" width="74" height="126" rx="30" fill="#e0e9e0" stroke="#9cb3a7" stroke-width="3"/>'+label(258,98,'Défauts ?')+label(185,186,'Je porte sur moi un regard très dur.'),
 person(65,112,'#a13b52','sad')+person(220,112,'#7c9b91')+person(280,112,'#7c9b91')+'<ellipse cx="249" cy="150" rx="69" ry="25" fill="none" stroke="#9cb3a7" stroke-width="2"/>'+label(185,186,'Je me sens à l’écart du groupe.'),
 person(100,112,'#a13b52','sad')+'<path d="M180 155v-28h35v-28h35V71h35V43h35" stroke="#9cb3a7" stroke-width="7" fill="none"/>'+label(250,30,'Réussir ?')+label(185,186,'Avant même d’essayer, je redoute l’échec.'),
 person(155,112,'#a13b52')+person(210,112,'#7c9b91')+'<path d="M152 80C72 35 290 28 218 81" fill="none" stroke="#a13b52" stroke-width="3"/>'+box(143,15,85,29,'Moi ? Nous ?')+label(185,186,'Mes envies se confondent avec celles de l’autre.'),
 person(110,112,'#a13b52','reach')+person(270,112,'#7c9b91')+box(158,40,69,34,'Décider ?')+label(185,186,'J’ai besoin d’être guidé pour me sentir capable.'),
 person(180,112,'#a13b52','sad')+'<path d="M60 60Q20 20 75 24Q105 -5 136 26Q178 22 159 61Z" fill="#c9d4d0"/>'+label(99,49,'Danger ?')+'<path d="M99 64l-9 18h15l-9 18" stroke="#a13b52" stroke-width="3" fill="none"/>'+box(242,40,86,34,'Et si… ?')+label(185,186,'J’anticipe une catastrophe difficile à affronter.'),
 person(82,112,'#7c9b91')+person(155,112,'#7c9b91')+person(282,112,'#a13b52','reach')+'<path d="M211 153V60" stroke="#9cb3a7" stroke-width="4"/>'+box(194,18,122,31,'Mon tour d’abord')+label(185,186,'Accepter les limites communes est difficile.'),
 person(112,112,'#a13b52','reach')+box(229,91,91,58,'Projet')+box(175,20,124,36,'Tout de suite !')+'<path d="M161 113h38" stroke="#a13b52" stroke-width="3" stroke-dasharray="4 7"/>'+label(185,186,'L’envie immédiate prend le pas sur mon objectif.'),
 person(116,112,'#a13b52','sad')+person(274,112,'#7c9b91')+box(47,24,75,31,'Oui…')+box(228,20,108,31,'À ma façon')+label(185,186,'Je retiens mon avis pour éviter le conflit.'),
 person(114,112,'#a13b52','reach')+person(279,112,'#7c9b91')+heart(201,70)+box(34,18,112,30,'Et moi, après ?')+label(185,186,'Je donne aux autres en oubliant mes besoins.'),
 person(179,112,'#a13b52','reach')+box(27,20,100,34,'Bravo ?')+box(245,20,102,34,'J’aime ?')+'<path d="M126 53L149 70M245 53L214 70" stroke="#9cb3a7" stroke-width="2"/>'+label(185,186,'Je cherche ma valeur dans le regard des autres.'),
 person(178,112,'#a13b52','sad')+'<circle cx="73" cy="46" r="22" fill="#e5bf6d"/><path d="M217 60Q192 26 228 24Q253 4 279 24Q323 20 313 60Z" fill="#a8b9b6"/><path d="M239 69l-4 14m27-14l-4 14m27-14l-4 14" stroke="#205c6a" stroke-width="3"/>'+label(185,186,'Mon attention va surtout vers ce qui menace.'),
 person(126,112,'#a13b52','sad')+box(225,38,87,42,'Erreur !')+'<path d="M228 115l48-35M268 71l20 20" stroke="#a13b52" stroke-width="7" stroke-linecap="round"/>'+label(185,186,'Je réponds à l’erreur par une grande sévérité.'),
 person(185,112,'#a13b52')+'<rect x="140" y="56" width="91" height="91" rx="12" fill="#edf2ef" fill-opacity=".72" stroke="#9cb3a7" stroke-width="3"/>'+heart(184,83)+box(32,23,116,30,'Ne rien montrer')+label(185,186,'Je garde mes émotions enfermées à l’intérieur.'),
 person(110,112,'#a13b52','reach')+'<path d="M201 155V55m43 100V35m43 120V15" stroke="#9cb3a7" stroke-width="6"/>'+box(184,20,84,28,'Encore plus')+label(185,186,'La barre monte et le repos attend toujours.')
 ][i];
 return `<svg viewBox="0 0 370 205" role="img" aria-label="${esc(sceneCaptions[i])}"><rect width="370" height="205" rx="18" fill="#eef1e8"/><path d="M25 161H345" stroke="#d7dfd5" stroke-width="2"/>${scene}</svg>`;
}
const sceneCaptions=['Une personne tend le bras vers un proche qui s’éloigne.','Un bouclier sépare deux personnes : la confiance est difficile.','Une personne seule cherche de l’écoute et du soutien.','Une personne se regarde dans un miroir en ne voyant que ses défauts.','Une personne se tient à distance d’un groupe.','Une personne hésite devant un escalier qui représente la réussite.','Deux personnes très liées ne distinguent plus leurs envies.','Une personne demande à une autre de guider sa décision.','Une personne inquiète anticipe des dangers autour d’elle.','Une personne veut passer avant les autres dans une file.','Une envie immédiate détourne une personne d’un projet à terminer.','Une personne dit oui alors qu’elle retient son propre avis.','Une personne donne son cœur et repousse ses propres besoins.','Une personne attend des signes d’approbation autour d’elle.','Une personne regarde l’orage et ne remarque pas le soleil.','Une erreur provoque un jugement sévère.','Une personne garde ses émotions dans une boîte fermée.','Une personne fait face à des barres de performance toujours plus hautes.'];
function render(){
 $('#filters').innerHTML=groups.map((g,i)=>`<button aria-pressed="${group===i}" data-group="${i}">${String(i+1).padStart(2,'0')} · ${esc(g)}</button>`).join('');
 const q=$('#search').value.toLocaleLowerCase('fr');$('#groupTitle').textContent=q?'Résultats de recherche':groups[group];
 const matching=schemas.map((s,i)=>({s,i})).filter(({s})=>!q||s.join(' ').toLocaleLowerCase('fr').includes(q));if(q&&!matching.some(x=>x.i===activeSchema)&&matching.length)activeSchema=matching[0].i;const chosen=matching.filter(x=>x.i===activeSchema);$('#schemaJump').innerHTML=matching.map(({s,i})=>`<option value="${i}" ${i===activeSchema?'selected':''}>${String(i+1).padStart(2,'0')} · ${esc(s[1])}</option>`).join('');$('#stepPosition').textContent=`Schéma ${activeSchema+1} sur 18`;$('#journeyFill').style.width=((activeSchema+1)/18*100)+'%';$('#previousSchema').disabled=activeSchema===0;$('#nextSchema').textContent=activeSchema===17?'Passer à mes réflexions →':'Schéma suivant →';
 $('#cards').innerHTML=chosen.map(({s,i})=>`<article class="card"><div class="comic">${figure(i)}<blockquote>« ${esc(s[5])} »</blockquote></div><div class="cardbody"><span class="num">SCHÉMA ${String(i+1).padStart(2,'0')} · ${esc(groups[s[0]])}</span><h3>${esc(s[1])}</h3><p><b>${esc(s[2])}</b></p><p>${esc(s[3])}</p><details><summary>Comprendre les origines possibles</summary><p>${esc(s[4])} Ce sont des pistes, pas une explication certaine de votre histoire.</p></details><p><b>Un besoin à explorer :</b> ${esc(s[6])}.</p><div class="scale"><fieldset><legend>À quel point je me reconnais ?</legend><div class="ratings">${Array.from({length:11},(_,n)=>`<button aria-label="${n} sur 10 : ${esc(s[1])}" aria-pressed="${state.ratings[i]===n}" data-rate="${i}" data-value="${n}">${n}</button>`).join('')}</div><div class="endpoints"><span>0 · Pas du tout</span><span>10 · Tout à fait</span></div></fieldset><button class="reset" data-reset="${i}">${state.ratings[i]===undefined?'Non renseigné':'Effacer cette note'}</button></div><label class="note" for="note-${i}">Un exemple dans ma vie (facultatif)</label><textarea id="note-${i}" data-note="${i}" rows="2" placeholder="Une situation, une émotion, une réaction…">${esc(state.notes[i]||'')}</textarea></div></article>`).join('')||'<p>Aucun schéma trouvé. Essayez un autre mot.</p>';
 updateChart();
}
function updateChart(){$('#stepAnswer').textContent=state.ratings[activeSchema]===undefined?'À votre choix · réponse facultative':'Ma réponse : '+state.ratings[activeSchema]+' / 10';let count=schemas.filter((s,i)=>Number.isInteger(state.ratings[i])).length;$('#progress').textContent=`${count} / 18 schémas renseignés`;$('#chart').innerHTML=schemas.map((s,i)=>`<div class="barrow"><span>${esc(s[1])}</span><div class="track" aria-hidden="true"><div class="fill" style="width:${(state.ratings[i]??0)*10}%"></div></div><span>${state.ratings[i]===undefined?'Non renseigné':state.ratings[i]+' / 10'}</span></div>`).join('');}
$('#filters').addEventListener('click',e=>{if(e.target.dataset.group!==undefined){group=Number(e.target.dataset.group);activeSchema=schemas.findIndex(s=>s[0]===group);$('#search').value='';render();}});
$('#cards').addEventListener('click',e=>{const t=e.target;if(t.dataset.rate!==undefined){state.ratings[t.dataset.rate]=Number(t.dataset.value);persist();const card=t.closest('.card');card.querySelectorAll('[data-rate]').forEach(b=>b.setAttribute('aria-pressed',String(b===t)));card.querySelector('[data-reset]').textContent='Effacer cette note';updateChart();}if(t.dataset.reset!==undefined){delete state.ratings[t.dataset.reset];persist();t.closest('.card').querySelectorAll('[data-rate]').forEach(b=>b.setAttribute('aria-pressed','false'));t.textContent='Non renseigné';updateChart();}});
$('#cards').addEventListener('input',e=>{if(e.target.dataset.note!==undefined){state.notes[e.target.dataset.note]=e.target.value;persist();}});$('#search').addEventListener('input',render);
$('#priority').insertAdjacentHTML('beforeend',schemas.map((s,i)=>`<option value="${i}">${esc(s[1])}</option>`).join(''));
for(const id of ['name','patientEmail','patientPhone','priority','situation','need','action']){$('#'+id).value=state[id];$('#'+id).addEventListener('input',e=>{state[id]=e.target.value;persist();});}
$('#save').addEventListener('change',()=>{if($('#save').checked)persist();else try{localStorage.removeItem(key);}catch{}});
$('#clear').onclick=()=>{if(confirm('Effacer les notes et réflexions de cette page et de cet appareil ?')){try{localStorage.removeItem(key);}catch{}state={ratings:{},notes:{},name:'',patientEmail:'',patientPhone:'',priority:'',situation:'',need:'',action:''};if(currentPdfUrl){URL.revokeObjectURL(currentPdfUrl);currentPdfUrl=null;}$('#pdfLinks').hidden=true;for(const id of ['name','patientEmail','patientPhone','priority','situation','need','action'])$('#'+id).value='';$('#save').checked=false;render();$('#status').textContent='Vos réponses ont été effacées.';}};
const clean=s=>String(s??'').replace(/[’‘]/g,"'").replace(/[“”]/g,'"').replace(/[–—]/g,'-').replace(/…/g,'...').replace(/\u202f/g,' ');
async function pdf(){
 if(!window.jspdf)throw Error('Le module PDF ne se charge pas. Rechargez la page.');
 const doc=new window.jspdf.jsPDF({unit:'mm',format:'a4'});let y=45,page=1;
 const logo='data:image/png;base64,';
 function header(){doc.setFillColor(249,247,242);doc.rect(0,0,210,297,'F');doc.addImage(logo,'PNG',18,10,43,26);doc.setTextColor(32,78,89);doc.setFont('helvetica','normal');doc.setFontSize(9);doc.text('MES SCHÉMAS | BILAN PERSONNEL',192,22,{align:'right'});doc.setDrawColor(211,220,211);doc.line(18,39,192,39);y=49;}
 function next(){doc.addPage();page++;header();}
 function room(h){if(y+h>275)next();}
 function text(s,size=11,bold=false,color=[32,78,89]){doc.setFont('helvetica',bold?'bold':'normal');doc.setFontSize(size);doc.setTextColor(...color);const lines=doc.splitTextToSize(clean(s),174);for(const l of lines){room(size*.45+2);doc.text(l,18,y);y+=size*.45+1;}y+=3;}
 header();text('Mon paysage du moment',24);text('Date : '+new Date().toLocaleDateString('fr-FR'));text('Prénom / pseudonyme : '+(state.name.trim()||'Non renseigné'));text('Adresse mail : '+(state.patientEmail.trim()||'Non renseignée'));text('Téléphone : '+(state.patientPhone.trim()||'Non renseigné'));text(schemas.filter((s,i)=>state.ratings[i]!==undefined).length+' schémas renseignés sur 18.');text('Échelle personnelle : 0 = pas du tout ; 5 = moyennement ; 10 = tout à fait.',10);text('Ce bilan est un support de discussion. Il ne constitue ni un diagnostic, ni le questionnaire de Young, ni une mesure validée. Aucun seuil clinique ou score global n’est calculé.',10);y+=4;
 for(let i=0;i<schemas.length;i++){room(13);doc.setFontSize(9);doc.setFont('helvetica','normal');doc.setTextColor(32,78,89);doc.text(clean(schemas[i][1]),18,y);let n=state.ratings[i];doc.text(n===undefined?'Non renseigné':n+' / 10',192,y,{align:'right'});doc.setFillColor(223,229,220);doc.roundedRect(18,y+2,174,2,1,1,'F');if(n>0){doc.setFillColor(156,61,82);doc.roundedRect(18,y+2,174*n/10,2,1,1,'F');}y+=11;}
 next();text('Mes repères, schéma par schéma',21);
 schemas.forEach((s,i)=>{room(36);text(String(i+1).padStart(2,'0')+' / '+s[1],14,true);text(groups[s[0]]+' | Reconnaissance : '+(state.ratings[i]===undefined?'non renseigné':state.ratings[i]+'/10'),9);text(s[2]+' '+s[3],10);text('Besoin à explorer : '+s[6]+'.',10);text('Mon exemple : '+(state.notes[i]?.trim()||'Non renseigné'),10);y+=5;});
 next();text('Préparer ma séance',23);for(const [title,value] of [['Ma priorité',state.priority!==''?schemas[Number(state.priority)]?.[1]:''],['La situation qui réveille ce schéma',state.situation],['Le besoin que je souhaite respecter',state.need],['Le petit pas que je pourrais essayer',state.action]]){room(25);text(title,13,true);text(value?.trim()||'Non renseigné');y+=6;}
 text('À relire avec mon psychologue',15,true);text('Les origines évoquées dans l’application sont des hypothèses possibles, pas des conclusions sur mon enfance. Un schéma est un fonctionnement qui peut évoluer ; il ne résume pas mon identité.',10);text('Source pédagogique : Fiches psychoéducation schémas - Extraits, document fourni par le thérapeute. Formulations adaptées pour ce support.',9);text('Contact : contact@ombaliz.com',10,true);text('Document personnel : je choisis son stockage et son partage.',9);
 const total=doc.getNumberOfPages();for(let p=1;p<=total;p++){doc.setPage(p);doc.setFontSize(8);doc.setTextColor(80,100,100);doc.text('Ombaliz Thérapie | Document personnel',18,287);doc.text(p+' / '+total,192,287,{align:'right'});}return doc;
}
let currentPdfUrl;
function offerPDF(d){
 if(currentPdfUrl)URL.revokeObjectURL(currentPdfUrl);
 currentPdfUrl=URL.createObjectURL(d.output('blob'));
 const box=$('#pdfLinks');box.hidden=false;
 $('#pdfFile').href=currentPdfUrl;
 $('#pdfOpen').href=currentPdfUrl;
 return currentPdfUrl;
}
async function download(){
 const b=$('#download');b.disabled=true;$('#status').textContent='Préparation de votre PDF…';
 try{const d=await pdf();offerPDF(d);$('#status').textContent='Votre PDF est prêt. Cliquez sur « Enregistrer le fichier PDF » ci-dessous. Sur iPhone, vous pouvez aussi ouvrir le PDF puis utiliser Partager → Enregistrer dans Fichiers.';$('#pdfFile').focus();}
 catch(e){$('#status').textContent='Le PDF ne peut pas être préparé : '+e.message;}
 finally{b.disabled=false;}
}
$('#download').onclick=download;
$('#share').onclick=async()=>{try{const d=await pdf();offerPDF(d);const file=new File([d.output('blob')],'Mon-bilan-schemas-Ombaliz.pdf',{type:'application/pdf'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Mon bilan Ombaliz'});$('#status').textContent='Le fichier a été remis au menu de partage.';}else{$('#status').textContent='Le partage direct est indisponible dans ce navigateur. Utilisez le lien « Enregistrer le fichier PDF », puis joignez-le à votre courriel.';$('#pdfFile').focus();}}catch(e){$('#status').textContent=e.name==='AbortError'?'Partage annulé. Le PDF reste disponible ci-dessous.':e.message;}};
$('#email').onclick=()=>{if(!$('#consent').checked){$('#status').textContent='Cochez votre choix de transmission avant de préparer le courriel.';$('#consent').focus();return;}location.href='mailto:contact@ombaliz.com?subject='+encodeURIComponent('Mon bilan des schémas - Ombaliz Thérapie')+'&body='+encodeURIComponent('Bonjour,\n\nJe souhaite partager mon bilan pour notre prochaine séance.\n\n[Joindre ici le fichier Mon-bilan-schemas-Ombaliz.pdf téléchargé depuis l’application.]\n\nBien cordialement');$('#status').textContent='Votre messagerie s’ouvre. Ajoutez le PDF et vérifiez le destinataire avant l’envoi.';};
$('#schemaJump').onchange=e=>{activeSchema=Number(e.target.value);group=schemas[activeSchema][0];render();};
function moveSchema(delta){activeSchema=Math.max(0,Math.min(17,activeSchema+delta));group=schemas[activeSchema][0];$('#search').value='';render();$('#cards').scrollIntoView({behavior:'smooth',block:'start'});$('#cards h3').setAttribute('tabindex','-1');$('#cards h3').focus({preventScroll:true});}
$('#previousSchema').onclick=()=>moveSchema(-1);$('#nextSchema').onclick=()=>{if(activeSchema===17){$('.reflection').scrollIntoView({behavior:'smooth'});}else moveSchema(1);};
$('#patientEmail').addEventListener('input',()=>{$('#emailHint').textContent=$('#patientEmail').validity.typeMismatch?'Vérifiez le format de votre adresse mail.':'';});
render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
